<?php
require_once __DIR__ . '/../config/database.php'; requireAdmin();
$pdo=null; $error=null; $dbError=null; $notice=null;
try {
 $pdo=db();
 if ($_SERVER['REQUEST_METHOD']==='POST') {
  if (!verifyAdminCsrf($_POST['csrf'] ?? null)) $error='Your form expired. Refresh the page and try again.';
  elseif (($_POST['action'] ?? '')==='create') {
   $tenantId=(int)($_POST['tenant_id'] ?? 0); $unitId=(int)($_POST['unit_id'] ?? 0); $type=(string)($_POST['bill_type'] ?? 'water'); $description=trim((string)($_POST['description'] ?? '')); $amount=(float)($_POST['amount'] ?? 0); $due=trim((string)($_POST['due_date'] ?? ''));
   if (!in_array($type,['water','electricity','rent','other'],true)||$tenantId<1||$unitId<1||$description===''||$amount<=0||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$due)) $error='Enter a tenant, unit, valid bill type, description, positive amount, and due date.';
   else { $q=$pdo->prepare("SELECT COUNT(*) FROM reservations WHERE tenant_id=:tenant AND unit_id=:unit AND status<>'cancelled'");$q->execute(['tenant'=>$tenantId,'unit'=>$unitId]);if(!(int)$q->fetchColumn())$error='The selected tenant has no active reservation for that unit.';else{$q=$pdo->prepare("INSERT INTO tenant_bills(tenant_id,unit_id,bill_type,description,amount,due_date)VALUES(:tenant,:unit,:type,:description,:amount,:due)");$q->execute(['tenant'=>$tenantId,'unit'=>$unitId,'type'=>$type,'description'=>$description,'amount'=>$amount,'due'=>$due]);header('Location: billing.php?notice=created');exit;}}
  } elseif (($_POST['action'] ?? '')==='status') {
   $id=(int)($_POST['id'] ?? 0);$status=(string)($_POST['status'] ?? 'submitted');if(!in_array($status,['unpaid','submitted','paid','overdue'],true))$status='submitted';
   $q=$pdo->prepare('UPDATE tenant_bills SET status=:status,paid_at=:paid_at WHERE id=:id');$q->execute(['status'=>$status,'paid_at'=>$status==='paid'?date('Y-m-d H:i:s'):null,'id'=>$id]);header('Location: billing.php?notice=updated');exit;
  }
 }
 $tenants=$pdo->query("SELECT DISTINCT t.id,t.full_name,t.email,u.id AS unit_id,u.unit_number,a.name AS apartment_name FROM tenants t JOIN reservations r ON r.tenant_id=t.id AND r.status<>'cancelled' JOIN units u ON u.id=r.unit_id JOIN apartments a ON a.id=u.apartment_id ORDER BY t.full_name")->fetchAll();
 $bills=$pdo->query("SELECT b.*,t.full_name,t.email,u.unit_number,a.name AS apartment_name FROM tenant_bills b JOIN tenants t ON t.id=b.tenant_id JOIN units u ON u.id=b.unit_id JOIN apartments a ON a.id=u.apartment_id ORDER BY FIELD(b.status,'submitted','unpaid','overdue','paid'),b.due_date ASC,b.id DESC")->fetchAll();
} catch(Throwable $ex){$dbError='Run sql/migrate_add_billing_policies.sql against the existing database, or import the updated schema for a new setup.';$tenants=$bills=[];}
$pageTitle='Tenant billing';$currentAdminPage='billing';require __DIR__.'/partials/header.php';
?><section class="admin-page-toolbar"><div><p class="admin-lede">Create water, electricity, rent, and other bills; review tenant-selected payment options and transaction numbers (demo only).</p></div><span class="toolbar-count"><?= count($bills) ?> bills</span></section><?php if($dbError): ?><div class="database-notice" role="status"><strong>Billing unavailable.</strong><span><?= e($dbError) ?></span></div><?php endif; ?><?php if(isset($_GET['notice'])): ?><div class="success-banner" role="status">Bill <?= e($_GET['notice']==='created'?'created':'updated') ?>.</div><?php endif; ?><?php if($error): ?><div class="form-alert" role="alert"><?= e($error) ?></div><?php endif; ?>
<section class="admin-form-card"><div class="admin-form-heading"><div><p class="eyebrow">NEW CHARGE</p><h2>Create a tenant bill</h2></div></div><?php if(!$tenants): ?><p>No active tenant/unit pair is available yet. A renter needs a linked reservation first.</p><?php else: ?><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= e(adminCsrfToken()) ?>"><input type="hidden" name="action" value="create"><label>Tenant &amp; unit<select name="tenant_id" id="bill-tenant" required><option value="">Choose tenant</option><?php foreach($tenants as $t): ?><option value="<?= (int)$t['id'] ?>" data-unit="<?= (int)$t['unit_id'] ?>"><?= e($t['full_name']) ?> · <?= e($t['apartment_name']) ?> / <?= e($t['unit_number']) ?></option><?php endforeach; ?></select></label><input type="hidden" name="unit_id" id="bill-unit" value="<?= (int)$tenants[0]['unit_id'] ?>"><label>Bill type<select name="bill_type"><option value="water">Water</option><option value="electricity">Electricity</option><option value="rent">Apartment rent</option><option value="other">Other</option></select></label><label>Description<input name="description" required placeholder="October water bill"></label><label>Amount (₱)<input type="number" name="amount" min="0.01" step="0.01" required></label><label>Due date<input type="date" name="due_date" required></label><div class="form-grid-full"><button class="button button-dark" type="submit">Create bill</button></div></form><?php endif; ?></section>
<div class="admin-panel admin-list-panel"><div class="admin-table-wrap"><table class="admin-table admin-table-wide"><thead><tr><th>Tenant / unit</th><th>Bill</th><th>Amount</th><th>Due</th><th>Tenant transaction number</th><th>Status / verify</th></tr></thead><tbody><?php foreach($bills as $b): ?><tr><td><strong><?= e($b['full_name']) ?></strong><small><?= e($b['apartment_name']) ?> · Unit <?= e($b['unit_number']) ?></small></td><td><?= e(ucfirst($b['bill_type'])) ?><small><?= e($b['description']) ?></small></td><td><?= pesos((float)$b['amount']) ?></td><td><?= e(date('M j, Y',strtotime($b['due_date']))) ?></td><td><?= $b['payment_reference']?'<code>'.e($b['payment_reference']).'</code>':'—' ?></td><td><form method="post" class="inline-status-form"><input type="hidden" name="csrf" value="<?= e(adminCsrfToken()) ?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?= (int)$b['id'] ?>"><select name="status"><option value="unpaid" <?= $b['status']==='unpaid'?'selected':'' ?>>Unpaid</option><option value="submitted" <?= $b['status']==='submitted'?'selected':'' ?>>Submitted</option><option value="paid" <?= $b['status']==='paid'?'selected':'' ?>>Paid / verified</option><option value="overdue" <?= $b['status']==='overdue'?'selected':'' ?>>Overdue</option></select><button type="submit">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div></div><script>const sel=document.getElementById('bill-tenant'),unit=document.getElementById('bill-unit');if(sel&&unit){const update=()=>unit.value=sel.selectedOptions[0]?.dataset.unit||'';sel.addEventListener('change',update);update()}</script><?php require __DIR__.'/partials/footer.php'; ?>
